#include<iostream>
#include<vector>
#include<algorithm>
using namespace std;

int main() {
    int b;
    while (cin >> b) {
        if (b == 0) break;

        vector<int> v(b);
        for (int i = 0; i < b; i++) {
            cin >> v[i];
        }

        int max_sum = 0, current_sum = 0;
        for (int i = 0; i < b; i++) {
            current_sum += v[i];
            if (current_sum < 0) current_sum = 0; // Reset if negative
            max_sum = max(max_sum, current_sum);
        }
        cout << max_sum << endl;
    }
}

